      t.v.ReflectorBuff = (num(t.v.ReflectorBuff) * num(item(G.l.P_Reflect, (3 - num(t.v.p)))));
      addTo(G.l.Num_G_ParticlesActive, (String((3 - num(t.v.p))) + ":StrongATK:0: : "));
      addTo(G.l.Num_G_ParticlesActive, (String((3 - num(t.v.p))) + ":gain1:0: : "));
      addTo(G.l.Num_G_ToBeReflected, t.v.startingID);
      addTo(G.l.Num_G_ToBeReflected, t.v.tempg);
      addTo(G.l.Num_G_ToBeReflected, (num(t.v.ReflectorBuff) * 1.5));
