  /** define yeash %s %s */
  function p_yeash(t: T, a_char: Value, a_state: Value): void {
    t.v.ReflectorBuff = "1";
    if (eq((String(a_char) + String(a_state)), "5NM")) {
      t.v.NonUniform = "1";
      t.v.hitboxID = item(G.l.NIZHONI_SAFEPROJECTILES, rt.pickRandom(1, 11));
      if ((eq(t.v.p, 1) && eq(G.v.gimmick1, 3))) {
        return;
      }
      if ((eq(t.v.p, 2) && eq(G.v.gimmick2, 3))) {
        return;
      }
      p_gim_set_Plus(t, t.v.p, "1", "+");
    }
    if (listContains(t.l.Local_Return2, "IsGrab")) {
      t.v.hitboxID = "Grab";
    }
    t.show();
    t.v.misc1 = item(G.l.P_States, (num(t.v.p) + 2));
    t.v.base_hitbox = "0";
    t.v.projectile = "1";
    rt.createClone(t, "_myself_");
    if (listContains(G.l.T_LO, 142)) {
      t.v.NonUniform = "1";
      for (let i10 = Math.round(num(item(G.l.T_C_Num, 142))); i10-- > 0; ) {
        rt.createClone(t, "_myself_");
      }
    }
    if (((eq(a_char, 10) && eq(a_state, "SM")) || eq(a_char, 23))) {
      for (let i11 = Math.round(num(rt.pickRandom(1, 3))); i11-- > 0; ) {
        rt.createClone(t, "_myself_");
      }
    }
    t.v.projectile = "0";
    t.v.base_hitbox = "1";
    t.v.NonUniform = "0";
  }

  /** define check projectile %s %s %s */
  function p_check_projectile(t: T, a_1_2: Value, a_state: Value, a_char: Value): void {
    if (listContains(t.l.Local_Return2, "Projectile")) {
      if ((eq(G.v.Num_storybattle, 2) && eq(t.v.p, 1))) {
        if (eq(item(G.l.Num_T_Chal, 73), 0)) {
          p_yeash(t, a_char, a_state);
        } else {
          rt.startSound(t, "locked");
        }
      } else {
        p_yeash(t, a_char, a_state);
      }
    }
    if (listContains(t.l.Local_Return2, "IsGrab")) {
      p_yeash(t, a_char, a_state);
      rt.startSound(t, "NN13");
    }
    if (listContains(t.l.Local_Return2, "CoinSwap")) {
      if (eq(item(G.l.P_Char, t.v.p), 27)) {
        replaceItem(G.l.P_Char, t.v.p, "34");
      } else {
        replaceItem(G.l.P_Char, t.v.p, 27);
      }
      rt.startSound(t, "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA");
      rt.broadcast("freeze");
      for (let i12 = 5; i12-- > 0; ) {
        p_zapfx(t, t.v.p);
      }
      rt.broadcast(("toshi" + String(t.v.p)));
    }
  }

